     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.util.Objects;
     6	
     7	public class Reservation {
     8	    public enum Status {
     9	        PENDING, CONFIRMED, CHECKED_IN, CHECKED_OUT, CANCELLED
    10	    }
    11	
    12	    public enum RatePlan {
    13	        STANDARD, NON_REFUNDABLE
    14	    }
    15	
    16	    private final long id;
    17	    private final int roomNumber;
    18	    private final String guestName;
    19	    private final String guestEmail;
    20	    private final GuestIdentification guestIdentification;
    21	    private final LocalDate checkIn;
    22	    private final LocalDate checkOut;
    23	    private final int guests;
    24	    private final RatePlan ratePlan;
    25	    private final long nights;
    26	    private final BigDecimal subtotal;
    27	    private final BigDecimal discount;
    28	    private final BigDecimal total;
    29	    private Status status;
    30	    private BigDecimal amountPaid;
    31	    private BigDecimal refund;
    32	
    33	    public Reservation(long id, int roomNumber, String guestName, String guestEmail,
    34	                      GuestIdentification guestIdentification, LocalDate checkIn, LocalDate checkOut,
    35	                      int guests, RatePlan ratePlan, long nights, BigDecimal subtotal,
    36	                      BigDecimal discount, BigDecimal total) {
    37	        this.id = id;
    38	        this.roomNumber = roomNumber;
    39	        this.guestName = guestName;
    40	        this.guestEmail = guestEmail;
    41	        this.guestIdentification = guestIdentification;
    42	        this.checkIn = checkIn;
    43	        this.checkOut = checkOut;
    44	        this.guests = guests;
    45	        this.ratePlan = ratePlan;
    46	        this.nights = nights;
    47	        this.subtotal = subtotal;
    48	        this.discount = discount;
    49	        this.total = total;
    50	        this.status = Status.PENDING;
    51	        this.amountPaid = BigDecimal.ZERO;
    52	        this.refund = null;
    53	    }
    54	
    55	    public long getId() { return id; }
    56	    public int getRoomNumber() { return roomNumber; }
    57	    public String getGuestName() { return guestName; }
    58	    public String getGuestEmail() { return guestEmail; }
    59	    public GuestIdentification getGuestIdentification() { return guestIdentification; }
    60	    public LocalDate getCheckIn() { return checkIn; }
    61	    public LocalDate getCheckOut() { return checkOut; }
