    70	    public BigDecimal getRefund() { return refund; }
    71	
    72	    public void confirm(BigDecimal amountPaid) {
    73	        Objects.requireNonNull(amountPaid);
    74	        if (status != Status.PENDING) {
    75	            throw new IllegalStateException("Can only confirm a PENDING reservation");
    76	        }
    77	        this.status = Status.CONFIRMED;
    78	        this.amountPaid = amountPaid;
    79	    }
    80	
    81	    public void checkIn() {
    82	        if (status != Status.CONFIRMED) {
    83	            throw new IllegalStateException("Can only check in a CONFIRMED reservation");
    84	        }
    85	        this.status = Status.CHECKED_IN;
    86	    }
    87	
    88	    public void checkOut() {
    89	        if (status != Status.CHECKED_IN) {
    90	            throw new IllegalStateException("Can only check out a CHECKED_IN reservation");
    91	        }
    92	        this.status = Status.CHECKED_OUT;
    93	    }
    94	
    95	    public void cancel() {
    96	        if (status != Status.PENDING && status != Status.CONFIRMED) {
    97	            throw new IllegalStateException("Can only cancel PENDING or CONFIRMED reservations");
    98	        }
    99	
   100	        if (status == Status.CONFIRMED) {
   101	            if (ratePlan == RatePlan.STANDARD) {
   102	                this.refund = amountPaid;
   103	            } else {
   104	                this.refund = BigDecimal.ZERO;
   105	            }
   106	        } else {
   107	            this.refund = BigDecimal.ZERO;
   108	        }
   109	
   110	        this.status = Status.CANCELLED;
   111	    }
   112	}
