=== service/DocumentGenerator.java
     1	package com.pousada.service;
     2	
     3	import com.pousada.domain.*;
     4	import java.math.BigDecimal;
     5	import java.math.RoundingMode;
     6	import java.time.LocalDate;
     7	import java.time.format.DateTimeFormatter;
     8	
     9	public class DocumentGenerator {
    10	    private static final DateTimeFormatter PT_DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    11	    private static final DateTimeFormatter EN_DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    12	
    13	    public static Document generateDocument(Reservation reservation, Room room) {
    14	        GuestIdentification id = reservation.getGuestIdentification();
    15	
    16	        if (id instanceof CpfIdentification cpfId) {
    17	            return generateComprovante(reservation, room, cpfId);
    18	        } else if (id instanceof CnpjIdentification cnpjId) {
    19	            return generateFatura(reservation, room, cnpjId);
    20	        } else if (id instanceof PassportIdentification passportId) {
    21	            return generateBookingReceipt(reservation, room, passportId);
    22	        }
    23	
    24	        throw new IllegalArgumentException("Unknown identification type");
    25	    }
    26	
    27	    private static Document generateComprovante(Reservation reservation, Room room, CpfIdentification cpfId) {
    28	        String checkIn = reservation.getCheckIn().format(PT_DATE_FORMAT);
    29	        String checkOut = reservation.getCheckOut().format(PT_DATE_FORMAT);
    30	
    31	        String text = String.format(
    32	            "Comprovante de reserva nº %d%n" +
    33	            "Hóspede: %s (CPF %s)%n" +
    34	            "Quarto: %d (%s)%n" +
    35	            "Entrada: %s | Saída: %s | %s%n" +
    36	            "Diárias: R$ %s%n" +
    37	            "%s" +
    38	            "Total: R$ %s",
    39	            reservation.getId(),
    40	            reservation.getGuestName(),
    41	            cpfId.guestCpf,
    42	            room.getNumber(),
    43	            room.getType(),
    44	            checkIn,
    45	            checkOut,
    46	            nightsLabel(reservation.getNights()),
    47	            formatPrice(reservation.getSubtotal()),
    48	            discountLine(reservation.getDiscount()),
    49	            formatPrice(reservation.getTotal())
    50	        );
    51	
    52	        return new Document("Comprovante de reserva", reservation.getId(),
    53	            reservation.getGuestName(), cpfId, null, null,
    54	            room.getNumber(), room.getType(), checkIn, checkOut,
    55	            reservation.getNights(), reservation.getSubtotal(),
    56	            reservation.getDiscount(), reservation.getTotal(), text);
    57	    }
    58	
    59	    private static Document generateFatura(Reservation reservation, Room room, CnpjIdentification cnpjId) {
    60	        String checkIn = reservation.getCheckIn().format(PT_DATE_FORMAT);
    61	        String checkOut = reservation.getCheckOut().format(PT_DATE_FORMAT);
    62	        BigDecimal issRetained = reservation.getTotal().multiply(new BigDecimal("0.05"))
    63	            .setScale(2, RoundingMode.HALF_EVEN);
    64	
    65	        String text = String.format(
    66	            "Fatura de hospedagem nº %d%n" +
    67	            "Empresa: %s (CNPJ %s)%n" +
    68	            "Hóspede: %s%n" +
    69	            "Quarto: %d (%s)%n" +
    70	            "Entrada: %s | Saída: %s | %s%n" +
    71	            "Diárias: R$ %s%n" +
    72	            "%s" +
    73	            "Total: R$ %s%n" +
    74	            "ISS retido (5%%): R$ %s",
    75	            reservation.getId(),
    76	            cnpjId.companyName,
    77	            cnpjId.companyCnpj,
    78	            reservation.getGuestName(),
    79	            room.getNumber(),
    80	            room.getType(),
    81	            checkIn,
    82	            checkOut,
    83	            nightsLabel(reservation.getNights()),
    84	            formatPrice(reservation.getSubtotal()),
    85	            discountLine(reservation.getDiscount()),
    86	            formatPrice(reservation.getTotal()),
    87	            formatPrice(issRetained)
    88	        );
    89	
    90	        return new Document("Fatura de hospedagem", reservation.getId(),
    91	            reservation.getGuestName(), null, cnpjId, null,
    92	            room.getNumber(), room.getType(), checkIn, checkOut,
    93	            reservation.getNights(), reservation.getSubtotal(),
    94	            reservation.getDiscount(), reservation.getTotal(), text, issRetained);
    95	    }
    96	
    97	    private static Document generateBookingReceipt(Reservation reservation, Room room, PassportIdentification passportId) {
    98	        String checkIn = reservation.getCheckIn().format(EN_DATE_FORMAT);
    99	        String checkOut = reservation.getCheckOut().format(EN_DATE_FORMAT);
   100	
   101	        String text = String.format(
   102	            "Booking receipt no. %d%n" +
   103	            "Guest: %s (passport %s, %s)%n" +
   104	            "Room: %d (%s)%n" +
   105	            "Check-in: %s | Check-out: %s | %s%n" +
   106	            "Nights: BRL %s%n" +
   107	            "%s" +
   108	            "Total: BRL %s",
   109	            reservation.getId(),
   110	            reservation.getGuestName(),
   111	            passportId.guestPassport,
   112	            passportId.guestCountry,
   113	            room.getNumber(),
   114	            room.getType(),
   115	            checkIn,
   116	            checkOut,
   117	            englishNightsLabel(reservation.getNights()),
   118	            formatPriceEnglish(reservation.getSubtotal()),
   119	            englishDiscountLine(reservation.getDiscount()),
   120	            formatPriceEnglish(reservation.getTotal())
   121	        );
   122	
   123	        return new Document("Booking receipt", reservation.getId(),
   124	            reservation.getGuestName(), null, null, passportId,
   125	            room.getNumber(), room.getType(), checkIn, checkOut,
   126	            reservation.getNights(), reservation.getSubtotal(),
   127	            reservation.getDiscount(), reservation.getTotal(), text);
   128	    }
   129	
   130	    private static String nightsLabel(long nights) {
   131	        return nights == 1 ? "1 diária" : nights + " diárias";
   132	    }
   133	
   134	    private static String englishNightsLabel(long nights) {
   135	        return nights == 1 ? "1 night" : nights + " nights";
   136	    }
   137	
   138	    private static String discountLine(BigDecimal discount) {
   139	        if (discount.compareTo(BigDecimal.ZERO) > 0) {
   140	            return "Desconto: R$ " + formatPrice(discount) + "\n";
   141	        }
   142	        return "";
   143	    }
   144	
   145	    private static String englishDiscountLine(BigDecimal discount) {
   146	        if (discount.compareTo(BigDecimal.ZERO) > 0) {
   147	            return "Discount: BRL " + formatPriceEnglish(discount) + "\n";
   148	        }
   149	        return "";
   150	    }
   151	
   152	    private static String formatPrice(BigDecimal amount) {
   153	        return String.format("%.2f", amount).replace(".", ",");
   154	    }
   155	
   156	    private static String formatPriceEnglish(BigDecimal amount) {
   157	        return String.format("%.2f", amount).replace(",", ".");
   158	    }
   159	}

