  1	package com.pousada.service;
  2	
  3	import com.pousada.domain.*;
  4	import com.pousada.repository.InMemoryRepository;
  5	import java.math.BigDecimal;
  6	import java.time.LocalDate;
  7	
  8	public class ReservationService {
  9	    private final InMemoryRepository repository = InMemoryRepository.getInstance();
 10	
 11	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
 12	                                         GuestIdentification guestIdentification, LocalDate checkIn,
 13	                                         LocalDate checkOut, int guests, Reservation.RatePlan ratePlan) {
 14	        Room room = repository.getRoomByNumber(roomNumber);
 15	        if (room == null) {
 16	            throw new ValidationException("ROOM_NOT_FOUND", "Room not found");
 17	        }
 18	
 19	        if (guests < 1) {
 20	            throw new ValidationException("INVALID_REQUEST", "At least one guest is required");
 21	        }
 22	
 23	        if (guests > room.getCapacity()) {
 24	            throw new ValidationException("CAPACITY_EXCEEDED", "Room capacity exceeded");
 25	        }
 26	
 27	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
 28	            throw new ValidationException("INVALID_REQUEST", "Check-out must be after check-in");
 29	        }
 30	
 31	        if (!repository.isRoomAvailable(roomNumber, checkIn, checkOut)) {
 32	            throw new ValidationException("ROOM_UNAVAILABLE", "Room is not available for the selected dates");
 33	        }
 34	
 35	        long nights = PricingService.getNights(checkIn, checkOut);
 36	        BigDecimal subtotal = PricingService.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
 37	        BigDecimal discount = PricingService.calculateDiscount(subtotal, ratePlan);
 38	        BigDecimal total = PricingService.calculateTotal(subtotal, discount);
 39	
 40	        Reservation reservation = new Reservation(0, roomNumber, guestName, guestEmail,
 41	            guestIdentification, checkIn, checkOut, guests, ratePlan,
 42	            nights, subtotal, discount, total);
 43	
 44	        long id = repository.saveReservation(reservation);
 45	        return repository.getReservation(id);
 46	    }
 47	
 48	    public Reservation confirmReservation(long reservationId, BigDecimal amountPaid) {
 49	        Reservation reservation = repository.getReservation(reservationId);
 50	        if (reservation == null) {
 51	            throw new ValidationException("RESERVATION_NOT_FOUND", "Reservation not found");
 52	        }
 53	
 54	        if (reservation.getStatus() != Reservation.Status.PENDING) {
 55	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Can only confirm a PENDING reservation");
 56	        }
 57	
 58	        reservation.confirm(amountPaid);
 59	
 60	        Room room = repository.getRoomByNumber(reservation.getRoomNumber());
 61	        Document document = DocumentGenerator.generateDocument(reservation, room);
 62	
 63	        String emailBody = generateConfirmationEmail(reservation, document);
 64	        repository.saveMessage("EMAIL", reservation.getGuestEmail(),
 65	            "Reserva confirmada - Pousada Maré Alta", emailBody);
 66	
 67	        return reservation;
 68	    }
 69	
 70	    public Reservation checkIn(long reservationId) {
 71	        Reservation reservation = repository.getReservation(reservationId);
 72	        if (reservation == null) {
 73	            throw new ValidationException("RESERVATION_NOT_FOUND", "Reservation not found");
 74	        }
 75	
 76	        if (reservation.getStatus() != Reservation.Status.CONFIRMED) {
 77	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Can only check in a CONFIRMED reservation");
 78	        }
 79	
 80	        reservation.checkIn();
 81	        return reservation;
 82	    }
 83	
 84	    public Document checkOut(long reservationId) {
 85	        Reservation reservation = repository.getReservation(reservationId);
 86	        if (reservation == null) {
 87	            throw new ValidationException("RESERVATION_NOT_FOUND", "Reservation not found");
 88	        }
 89	
 90	        if (reservation.getStatus() != Reservation.Status.CHECKED_IN) {
 91	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Can only check out a CHECKED_IN reservation");
 92	        }
 93	
 94	        reservation.checkOut();
 95	        Room room = repository.getRoomByNumber(reservation.getRoomNumber());
 96	        return DocumentGenerator.generateDocument(reservation, room);
 97	    }
 98	
 99	    public Reservation cancelReservation(long reservationId) {
100	        Reservation reservation = repository.getReservation(reservationId);
101	        if (reservation == null) {
102	            throw new ValidationException("RESERVATION_NOT_FOUND", "Reservation not found");
103	        }
104	
105	        if (reservation.getStatus() != Reservation.Status.PENDING &&
106	            reservation.getStatus() != Reservation.Status.CONFIRMED) {
107	            throw new ValidationException("OPERATION_NOT_ALLOWED",
108	                "Can only cancel PENDING or CONFIRMED reservations");
109	        }
110	
111	        reservation.cancel();
112	        return reservation;
113	    }
114	
115	    public Document getDocument(long reservationId) {
116	        Reservation reservation = repository.getReservation(reservationId);
117	        if (reservation == null) {
118	            throw new ValidationException("RESERVATION_NOT_FOUND", "Reservation not found");
119	        }
120	
121	        if (reservation.getStatus() != Reservation.Status.CONFIRMED &&
122	            reservation.getStatus() != Reservation.Status.CHECKED_IN &&
123	            reservation.getStatus() != Reservation.Status.CHECKED_OUT) {
124	            throw new ValidationException("OPERATION_NOT_ALLOWED",
125	                "Document is only available for paid reservations");
126	        }
127	
128	        Room room = repository.getRoomByNumber(reservation.getRoomNumber());
129	        return DocumentGenerator.generateDocument(reservation, room);
130	    }
131	
132	    private String generateConfirmationEmail(Reservation reservation, Document document) {
133	        return String.format(
134	            "Olá, %s!%n%n" +
135	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:%n%n" +
136	            "%s%n%n" +
137	            "A entrada é a partir das 14h, e a saída, até as 12h.%n" +
138	            "Até breve!",
139	            reservation.getGuestName(),
140	            document.getText()
141	        );
142	    }
143	
144	    public static class ValidationException extends RuntimeException {
145	        private final String errorCode;
146	
147	        public ValidationException(String errorCode, String message) {
148	            super(message);
149	            this.errorCode = errorCode;
150	        }
151	
152	        public String getErrorCode() {
153	            return errorCode;
154	        }
155	    }
156	}
157	package com.pousada.service;
158	
159	import com.pousada.domain.Reservation;
160	import java.math.BigDecimal;
161	import java.math.RoundingMode;
162	import java.time.LocalDate;
163	import java.time.Month;
164	
165	public class PricingService {
166	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
167	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
168	
169	    public static boolean isHighSeason(LocalDate date) {
170	        Month month = date.getMonth();
171	        int dayOfMonth = date.getDayOfMonth();
172	
173	        return (month == Month.DECEMBER && dayOfMonth >= 15) ||
174	               month == Month.JANUARY ||
175	               month == Month.FEBRUARY ||
176	               month == Month.JULY;
177	    }
178	
179	    public static BigDecimal getNightlyRate(BigDecimal baseRate, LocalDate date) {
180	        if (isHighSeason(date)) {
181	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER)
182	                .setScale(2, RoundingMode.HALF_EVEN);
183	        }
184	        return baseRate.setScale(2, RoundingMode.HALF_EVEN);
185	    }
186	
187	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
188	        BigDecimal subtotal = BigDecimal.ZERO;
189	        LocalDate current = checkIn;
190	
191	        while (current.isBefore(checkOut)) {
192	            BigDecimal nightlyRate = getNightlyRate(baseRate, current);
193	            subtotal = subtotal.add(nightlyRate);
194	            current = current.plusDays(1);
195	        }
196	
197	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
198	    }
199	
200	    public static BigDecimal calculateDiscount(BigDecimal subtotal, Reservation.RatePlan ratePlan) {
201	        if (ratePlan == Reservation.RatePlan.NON_REFUNDABLE) {
202	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE)
203	                .setScale(2, RoundingMode.HALF_EVEN);
204	        }
205	        return BigDecimal.ZERO;
206	    }
207	
208	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
209	        return subtotal.subtract(discount)
210	            .setScale(2, RoundingMode.HALF_EVEN);
211	    }
212	
213	    public static long getNights(LocalDate checkIn, LocalDate checkOut) {
214	        return java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
215	    }
216	}
