   291	        if (request.guestCpf != null) {
   292	            count++;
   293	            result = new CpfIdentification(request.guestCpf);
   294	        }
   295	        if (request.companyCnpj != null && request.companyName != null) {
   296	            count++;
   297	            result = new CnpjIdentification(request.companyCnpj, request.companyName);
   298	        }
   299	        if (request.guestPassport != null && request.guestCountry != null) {
   300	            count++;
   301	            result = new PassportIdentification(request.guestPassport, request.guestCountry);
   302	        }
   303	
   304	        if (count != 1) {
   305	            return null;
   306	        }
   307	        return result;
