   333	package com.pousada.service;
   334	
   335	import com.pousada.domain.Reservation;
   336	import com.pousada.domain.Room;
   337	import com.pousada.repository.InMemoryRepository;
   338	import java.math.BigDecimal;
   339	import java.time.LocalDate;
   340	import java.time.format.DateTimeFormatter;
   341	import java.util.*;
   342	
   343	public class ReportService {
   344	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
   345	    private final InMemoryRepository repository = InMemoryRepository.getInstance();
   346	
   347	    public String generateOccupancyReport(LocalDate date) {
   348	        StringBuilder csv = new StringBuilder();
   349	        csv.append("room,type,reservation,check_in,check_out\n");
   350	
   351	        List<Room> rooms = new ArrayList<>(repository.getAllRooms());
   352	        rooms.sort(Comparator.comparingInt(Room::getNumber));
   353	
   354	        int occupiedRooms = 0;
   355	
   356	        for (Room room : rooms) {
   357	            List<Reservation> reservations = repository.getReservationsByRoomAndDate(room.getNumber(), date);
   358	            if (!reservations.isEmpty()) {
   359	                for (Reservation res : reservations) {
   360	                    csv.append(String.format("%d,%s,%d,%s,%s\n",
   361	                        room.getNumber(),
   362	                        room.getType(),
   363	                        res.getId(),
   364	                        res.getCheckIn().format(DATE_FORMAT),
   365	                        res.getCheckOut().format(DATE_FORMAT)
   366	                    ));
   367	                    occupiedRooms++;
   368	                }
   369	            }
   370	        }
   371	
   372	        csv.append(String.format("total,%d/%d\n", occupiedRooms, rooms.size()));
   373	
   374	        return csv.toString();
   375	    }
   376	
   377	    public String generateRevenueReport(int year, int month) {
   378	        StringBuilder csv = new StringBuilder();
   379	        csv.append("reservation,room,check_in,check_out,status,amount\n");
   380	
   381	        // Get all reservations for the month, including cancelled ones
   382	        List<Reservation> allReservations = new ArrayList<>(repository.getAllReservations());
   383	        List<Reservation> reservations = allReservations.stream()
   384	            .filter(r -> r.getCheckIn().getYear() == year && r.getCheckIn().getMonthValue() == month)
   385	            .filter(r -> r.getStatus() == Reservation.Status.CONFIRMED ||
   386	                         r.getStatus() == Reservation.Status.CHECKED_IN ||
   387	                         r.getStatus() == Reservation.Status.CHECKED_OUT ||
   388	                         r.getStatus() == Reservation.Status.CANCELLED)
   389	            .sorted(Comparator.comparing(Reservation::getCheckIn)
   390	                .thenComparingLong(Reservation::getId))
   391	            .toList();
   392	
   393	        BigDecimal totalAmount = BigDecimal.ZERO;
   394	
   395	        for (Reservation res : reservations) {
   396	            BigDecimal amount = calculateMoneyRetained(res);
   397	            totalAmount = totalAmount.add(amount);
   398	
   399	            csv.append(String.format("%d,%d,%s,%s,%s,%s\n",
   400	                res.getId(),
   401	                res.getRoomNumber(),
   402	                res.getCheckIn().format(DATE_FORMAT),
   403	                res.getCheckOut().format(DATE_FORMAT),
   404	                res.getStatus(),
   405	                formatCsvPrice(amount)
   406	            ));
   407	        }
   408	
   409	        csv.append(String.format("total,%.2f\n", totalAmount));
   410	
   411	        return csv.toString();
   412	    }
   413	
   414	    private BigDecimal calculateMoneyRetained(Reservation reservation) {
   415	        BigDecimal retained = reservation.getAmountPaid();
   416	
   417	        if (reservation.getStatus() == Reservation.Status.CANCELLED) {
   418	            BigDecimal refunded = reservation.getRefund() != null ? reservation.getRefund() : BigDecimal.ZERO;
   419	            retained = retained.subtract(refunded);
   420	        }
   421	
   422	        return retained;
   423	    }
   424	
   425	    private String formatCsvPrice(BigDecimal amount) {
   426	        return String.format("%.2f", amount);
   427	    }
   428	}
