     8	import java.time.format.DateTimeFormatter;
     9	import java.util.*;
    10	
    11	public class ReportService {
    12	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    13	    private final InMemoryRepository repository = InMemoryRepository.getInstance();
    14	
    15	    public String generateOccupancyReport(LocalDate date) {
    16	        StringBuilder csv = new StringBuilder();
    17	        csv.append("room,type,reservation,check_in,check_out\n");
    18	
    19	        List<Room> rooms = new ArrayList<>(repository.getAllRooms());
    20	        rooms.sort(Comparator.comparingInt(Room::getNumber));
    21	
    22	        int occupiedRooms = 0;
    23	
    24	        for (Room room : rooms) {
    25	            List<Reservation> reservations = repository.getReservationsByRoomAndDate(room.getNumber(), date);
    26	            if (!reservations.isEmpty()) {
    27	                for (Reservation res : reservations) {
    28	                    csv.append(String.format("%d,%s,%d,%s,%s\n",
    29	                        room.getNumber(),
    30	                        room.getType(),
    31	                        res.getId(),
    32	                        res.getCheckIn().format(DATE_FORMAT),
    33	                        res.getCheckOut().format(DATE_FORMAT)
    34	                    ));
    35	                    occupiedRooms++;
    36	                }
    37	            }
    38	        }
    39	
    40	        csv.append(String.format("total,%d/%d\n", occupiedRooms, rooms.size()));
    41	
    42	        return csv.toString();
    43	    }
    44	
    45	    public String generateRevenueReport(int year, int month) {
    46	        StringBuilder csv = new StringBuilder();
    47	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    48	
    49	        // Get all reservations for the month, including cancelled ones
    50	        List<Reservation> allReservations = new ArrayList<>(repository.getAllReservations());
    51	        List<Reservation> reservations = allReservations.stream()
    52	            .filter(r -> r.getCheckIn().getYear() == year && r.getCheckIn().getMonthValue() == month)
    53	            .filter(r -> r.getStatus() == Reservation.Status.CONFIRMED ||
    54	                         r.getStatus() == Reservation.Status.CHECKED_IN ||
    55	                         r.getStatus() == Reservation.Status.CHECKED_OUT ||
    56	                         r.getStatus() == Reservation.Status.CANCELLED)
    57	            .sorted(Comparator.comparing(Reservation::getCheckIn)
    58	                .thenComparingLong(Reservation::getId))
    59	            .toList();
    60	
    61	        BigDecimal totalAmount = BigDecimal.ZERO;
    62	
    63	        for (Reservation res : reservations) {
    64	            BigDecimal amount = calculateMoneyRetained(res);
    65	            totalAmount = totalAmount.add(amount);
    66	
    67	            csv.append(String.format("%d,%d,%s,%s,%s,%s\n",
    68	                res.getId(),
    69	                res.getRoomNumber(),
    70	                res.getCheckIn().format(DATE_FORMAT),
    71	                res.getCheckOut().format(DATE_FORMAT),
    72	                res.getStatus(),
    73	                formatCsvPrice(amount)
    74	            ));
    75	        }
    76	
    77	        csv.append(String.format("total,%.2f\n", totalAmount));
    78	
    79	        return csv.toString();
    80	    }
    81	
    82	    private BigDecimal calculateMoneyRetained(Reservation reservation) {
    83	        BigDecimal retained = reservation.getAmountPaid();
    84	
    85	        if (reservation.getStatus() == Reservation.Status.CANCELLED) {
    86	            BigDecimal refunded = reservation.getRefund() != null ? reservation.getRefund() : BigDecimal.ZERO;
    87	            retained = retained.subtract(refunded);
    88	        }
    89	
    90	        return retained;
    91	    }
    92	
    93	    private String formatCsvPrice(BigDecimal amount) {
    94	        return String.format("%.2f", amount);
    95	    }
    96	}
